#' Build the hierarchical NIMBLE model
#'
#' Constructs the NIMBLE model code for the TOPALS Poisson model with spatial and non-spatial random effects at spline knots
#'
#' @param config List containing model dimensions, spline basis coefficients, adjacency information, and MCMC settings
#'
#' @return A NIMBLE model definition generated by `nimbleCode()`

build_nimble_code <- function(config) {
  N_ages <- config$dims$N_ages
  N_knots <- config$dims$N_knots
  N_tracts <- config$dims$N_tracts
  sumNumNeigh <- config$adj$sumNumNeigh

  nimbleCode({
    for (i in 1:N_tracts) {
      for (k in 1:N_ages) {
        Y[i, k] ~ dpois(theta[i, k])
        theta[i, k] <- n[i, k] * lambda[i, k]
        lambda[i, k] <- lambda_star[k] * exp(inprod(betas[i, 1:N_knots], coef[k, 1:N_knots]))
      }

      for (j in 1:N_knots) {
        betas[i, j] <- beta0[j] + nonspat[i, j] + betaij[j, i]
        nonspat[i, j] ~ dnorm(0, inv_tauns[j])
      }
    }

    for (j in 1:N_knots) {
      betaij[j, 1:N_tracts] ~ dcar_normal(
        adj[1:sumNumNeigh],
        weights[1:sumNumNeigh],
        num[1:N_tracts],
        inv_tau[j],
        zero_mean = 1
      )

      beta0[j] ~ dnorm(0, 0.001)

      inv_tau[j] ~ dgamma(1, 0.14)
      tau[j] <- 1 / inv_tau[j]

      inv_tauns[j] ~ dgamma(1, 0.01)
      tauns[j] <- 1 / inv_tauns[j]
    }

    for (h in 1:sumNumNeigh) {
      weights[h] <- 1
    }
  })
}

#' Run NIMBLE model for a single sex-period strata
#'
#'
#' @param sex_years_var Integer identifier for the sex-period strata to model
#' @param death_rates_tract Dataframe containing tract-, period-, age-, sex-specific mortality, population, and mortality rates
#' @param death_rates_age Dataframe containing period-, age-, and sex-specific mortality, population, and mortality rates (used for standard age schedule)
#' @param config List containing model dimensions, spline basis coefficients, adjacency information, and MCMC settings
#' @param model_code NIMBLE model definition produced bt `build_nimble_code()`
#'
#' @return A list containing posterior MCMC output from the fitted model

run_nimble_single <- function(
  sex_years_var,
  death_rates_tract,
  death_rates_age,
  config,
  model_code
) {
  set.seed(1234)

  # --- Data prep ---
  deaths <- death_rates_tract %>%
    filter(sex_years == sex_years_var) %>%
    select(GEOID, age, deaths, tract) %>%
    pivot_wider(names_from = age, values_from = deaths) %>%
    arrange(tract) %>%
    select(-tract)

  pop <- death_rates_tract %>%
    filter(sex_years == sex_years_var) %>%
    select(GEOID, age, pop, tract) %>%
    pivot_wider(names_from = age, values_from = pop) %>%
    arrange(tract) %>%
    select(-tract)

  Y <- as.matrix(select(deaths, -GEOID))
  n <- as.matrix(select(pop, -GEOID))

  theta_star <- death_rates_age %>%
    filter(sex_years == sex_years_var) %>%
    arrange(age) %>%
    pull(theta_star)

  # Run model
  out <- nimbleMCMC(
    code = model_code,
    data = list(Y = Y),
    constants = list(
      n           = n,
      lambda_star = exp(theta_star),
      coef        = config$coef,
      N_knots     = config$dims$N_knots,
      N_tracts    = config$dims$N_tracts,
      N_ages      = config$dims$N_ages,
      adj         = config$adj$adj,
      num         = config$adj$num,
      sumNumNeigh = config$adj$sumNumNeigh
    ),
    inits = list(
      tau = rep(100, config$dims$N_knots),
      tauns = rep(100, config$dims$N_knots),
      betaij = matrix(0,
        nrow = config$dims$N_knots,
        ncol = config$dims$N_tracts
      ),
      nonspat = matrix(0,
        nrow = config$dims$N_tracts,
        ncol = config$dims$N_knots
      ),
      beta0 = rep(0, config$dims$N_knots)
    ),
    monitors = c("lambda", "tau", "tauns", "beta0", "betaij", "nonspat"),
    niter = config$mcmc$niter,
    nburnin = config$mcmc$nburnin,
    thin = config$mcmc$thin
  )

  list(
    output = out
  )
}

#' Run NIMBLE models in parallel
#'
#' @param death_rates_tract Dataframe containing tract-, period-, age-, sex-specific mortality, population, and mortality rates
#' @param death_rates_age Dataframe containing period-, age-, and sex-specific mortality, population, and mortality rates (used for standard age schedule)
#' @param config List containing model dimensions, spline basis coefficients, adjacency information, and MCMC settings
#' @param label Characted label used in runtime messages
#' @param workers Number of parallel workers -- defaults to the minimum of number of cores - 1 and the number of sex x periods combinations
#' @param save_path Optional file path used to save model results
#' @param obj_name Name assigned to the saved object
#'
#' @return A named list of fitted NIMBLE model outputs with one element for each sex-period strata

run_nimble_parallel <- function(
  death_rates_tract,
  death_rates_age,
  config,
  label,
  workers = min(
    parallel::detectCores() - 1,
    length(unique(death_rates_tract$sex_years))
  ),
  save_path = NULL,
  obj_name = "nimble_results"
) {
  sex_years_vars <- sort(unique(death_rates_tract$sex_years))

  model_code <- build_nimble_code(config)

  plan(multisession, workers = workers)
  on.exit(plan(sequential))

  start_time <- Sys.time()

  results <- furrr::future_map(
    sex_years_vars,
    \(sy) run_nimble_single(
      sex_years_var     = sy,
      death_rates_tract = death_rates_tract,
      death_rates_age   = death_rates_age,
      config            = config,
      model_code        = model_code
    ),
    .options = furrr::furrr_options(seed = TRUE)
  )

  names(results) <- sex_years_vars

  elapsed <- as.numeric(difftime(Sys.time(), start_time, units = "hours"))
  cat(sprintf("%s nimble models took %.2f hours to run.\n", label, elapsed))


  if (!is.null(save_path)) {
    tmp_env <- new.env()
    tmp_env[[obj_name]] <- results

    save(
      list = obj_name,
      file = save_path,
      envir = tmp_env
    )

    cat(sprintf(
      "Saved object '%s' to %s\n",
      obj_name,
      save_path
    ))
  }

  results
}
